import { defineCard } from "../define.js";

// EDHREC rank 11121.
//
// Rulings:
//   [2020-09-25] The mana generated by Base Camp's last ability can't be spent to activate
//     abilities of cards that aren't on the battlefield or to pay a cost in a resolving triggered
//     ability.

const PARTY = ["Cleric", "Rogue", "Warrior", "Wizard"];
const SPEND_TEXT =
  "Spend this mana only to cast a Cleric, Rogue, Warrior, or Wizard spell or to activate an ability of a Cleric, Rogue, Warrior, or Wizard.";

export default defineCard({
  name: "Base Camp",
  colors: [],
  types: ["land"],
  text: `This land enters tapped.\n{T}: Add {C}.\n{T}: Add one mana of any color. ${SPEND_TEXT}`,
  activated: [
    {
      cost: { mana: null, tap: true },
      targets: [],
      effect: { kind: "add-mana", mana: "C", amount: 1 },
      resolve: null,
      text: "{T}: Add {C}.",
    },
    {
      cost: { mana: null, tap: true },
      targets: [],
      // `abilityOf` is a permanent's ability only (its ruling).
      effect: {
        kind: "add-mana",
        mana: "any-color",
        amount: 1,
        spendOnly: { spell: { subtypes: PARTY }, abilityOf: { subtypes: PARTY }, text: SPEND_TEXT },
      },
      resolve: null,
      text: `{T}: Add one mana of any color. ${SPEND_TEXT}`,
    },
  ],
  static: [
    {
      affects: { scope: "self" },
      replacement: { event: "enters-battlefield", tapped: true },
      text: "This land enters tapped.",
    },
  ],
});
